import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { texture, uv, normalLocal, positionLocal, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new THREE.Group();
  root.name = 'hub-features-divider';

  const inner = new THREE.Group();
  root.add(inner);

  // ---- placeholder textures filled asynchronously via ctx loaders ----
  const colorTex = new THREE.Texture();
  const dispTex = new THREE.Texture();

  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = config.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png';

  ctx.textureLoader
    .loadTexture(imageUrl)
    .then((tex) => {
      colorTex.image = tex.image;
      colorTex.colorSpace = tex.colorSpace;
      colorTex.wrapS = tex.wrapS;
      colorTex.wrapT = tex.wrapT;
      colorTex.needsUpdate = true;
    })
    .catch(() => {});

  ctx.textureLoader
    .loadTexture(depthUrl)
    .then((tex) => {
      dispTex.image = tex.image;
      dispTex.needsUpdate = true;
    })
    .catch(() => {});

  const displacementScale = uniform(0.03);

  // ---- machined rule (thin tessellated displaced plane) ----
  const ruleMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.ink),
    metalness: 0.5,
    roughness: 0.53,
  });
  ruleMat.colorNode = texture(colorTex, uv());
  ruleMat.positionNode = positionLocal.add(
    normalLocal.mul(texture(dispTex, uv()).r.sub(0.5).mul(displacementScale))
  );

  const ruleGeo = new THREE.PlaneGeometry(3.1, 0.22, 64, 64);
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  inner.add(ruleMesh);

  // ---- brushed edge rails (paper tone, subtle metal) ----
  const edgeMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    metalness: 0.32,
    roughness: 0.58,
  });
  const edgeGeo = new THREE.BoxGeometry(3.1, 0.012, 0.03);
  const edgeTop = new THREE.Mesh(edgeGeo, edgeMat);
  edgeTop.position.set(0, 0.11, 0.02);
  inner.add(edgeTop);
  const edgeBottom = new THREE.Mesh(edgeGeo, edgeMat);
  edgeBottom.position.set(0, -0.11, 0.02);
  inner.add(edgeBottom);

  // ---- center jewel (accent, faceted, subtly transmissive) ----
  const jewelGeo = new THREE.OctahedronGeometry(0.14, 0);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.accent),
    metalness: 0.15,
    roughness: 0.18,
    clearcoat: 0.22,
    clearcoatRoughness: 0.12,
    transmission: 0.32,
    ior: 1.5,
    thickness: 0.22,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 0.55,
  });
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.09);
  jewel.rotation.set(0.4, 0.4, 0);
  inner.add(jewel);

  // ---- small machined pin mounts flanking the jewel ----
  const pinGeo = new THREE.SphereGeometry(0.035, 16, 16);
  const pinMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    metalness: 0.6,
    roughness: 0.35,
  });
  const pinLeft = new THREE.Mesh(pinGeo, pinMat);
  pinLeft.position.set(-0.22, 0, 0.03);
  inner.add(pinLeft);
  const pinRight = new THREE.Mesh(pinGeo, pinMat);
  pinRight.position.set(0.22, 0, 0.03);
  inner.add(pinRight);

  // ---- node-local rim/key light (accent hue on jewel only) ----
  const rim = new THREE.PointLight(new THREE.Color(colors.accent), 1.0, 2.2, 2.0);
  rim.position.set(0.3, 0.25, 0.6);
  inner.add(rim);

  const key = new THREE.DirectionalLight(new THREE.Color(colors.paper), 0.45);
  key.position.set(-0.6, 0.5, 1.0);
  inner.add(key);

  // ---- soft depth-separation shadow plane behind the rule ----
  const shadowMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    roughness: 1,
    metalness: 0,
    transparent: true,
    opacity: 0.32,
  });
  const shadowGeo = new THREE.PlaneGeometry(3.6, 0.7);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.02, -0.05);
  inner.add(shadowMesh);

  // ---- idle motion: single slow breathing on the jewel only ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(jewel.scale, { x: 1.05, y: 1.05, z: 1.05, duration: 2.6, ease: 'sine.inOut' });

  // ---- required subtle parallax on the tessellated plane ----
  const parallax = ctx.primitives['parallax-scroll']
    ? ctx.primitives['parallax-scroll'](inner, { strength: 0.05, trigger: 'scroll' })
    : null;

  // ---- apply any spec-listed cinematic primitives (none configured) ----
  const appliedPrimitives = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const p of primitiveConfigs) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      appliedPrimitives.push(fn(inner, p.params ?? {}));
    }
  }

  // ---- interactions ----
  root.userData.handlers = {
    onPointerOver: () => {
      gsap.killTweensOf(inner.position);
      gsap.to(inner.position, { y: 0.15, duration: 0.3, ease: 'power3.out' });
    },
    onPointerOut: () => {
      gsap.killTweensOf(inner.position);
      gsap.to(inner.position, { y: 0, duration: 0.4, ease: 'power2.out' });
    },
    onClick: () => {
      gsap.killTweensOf(inner.scale);
      gsap.to(inner.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-features.select', { id: config.id ?? 'hub-features-divider' });
    },
  };

  root.userData.cleanup = () => {
    idleTl.kill();
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);

    parallax?.cleanup?.();
    for (const p of appliedPrimitives) p.cleanup?.();

    ruleGeo.dispose();
    ruleMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    pinGeo.dispose();
    pinMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    colorTex.dispose();
    dispTex.dispose();

    inner.remove(rim, key);
  };

  return root;
}
